import type {SpanNode} from '../../../utils/tracing'

export interface DecoratedNode extends SpanNode {
  duration: number
  depth: number
  children: DecoratedNode[]
}

/**
 * Same as DecoratedNode, but with string fields instead of number to work around Primer DataTable sorting bugs.
 */
export type StringyNode = Omit<DecoratedNode, 'startTime' | 'endTime' | 'duration' | 'children'> & {
  startTime: string
  endTime: string
  duration: string
  children: StringyNode[]
  hasData: string
}

/**
 * Adds depth field to each node and calculates min and max times for the entire tree.
 * And adds duration field to each node.
 */
export function decorateTree(
  node: Readonly<SpanNode>,
  depth = 0,
): {node: DecoratedNode; minTime: number; maxTime: number; maxDepth: number} {
  const startTime = node.startTime
  const endTime = node.endTime
  let minTime = startTime
  let maxTime = endTime
  let maxDepth = depth

  const decoratedChildren: DecoratedNode[] = node.children.map(child => {
    const result = decorateTree(child, depth + 1)
    minTime = Math.min(minTime, result.minTime)
    maxTime = Math.max(maxTime, result.maxTime)
    maxDepth = Math.max(maxDepth, result.maxDepth)
    return result.node
  })

  const decoratedNode: DecoratedNode = {
    ...node,
    startTime,
    endTime,
    duration: endTime - startTime,
    depth,
    children: decoratedChildren,
  }

  return {node: decoratedNode, minTime, maxTime, maxDepth}
}

/**
 * Subtracts minTime from startTime and endTime of each node in the tree.
 */
export function fixTimes(node: DecoratedNode, minTime: number, maxTime: number): DecoratedNode {
  const fixedChildren = node.children.map(child => fixTimes(child, minTime, maxTime))
  return {
    ...node,
    startTime: node.startTime - minTime,
    endTime: node.endTime - minTime,
    children: fixedChildren,
  }
}

export function stringifyTree(node: DecoratedNode): StringyNode {
  return {
    ...node,
    startTime: node.startTime.toString(),
    endTime: node.endTime.toString(),
    duration: node.duration.toString(),
    children: node.children.map(stringifyTree),
    hasData: hasLLMTracerData(node) ? 'Yes' : 'No',
  }
}

/**
 * Checks if a span has LLMTracer data (sessionId, userId, input, output, or metadata).
 */
export function hasLLMTracerData(node: DecoratedNode | StringyNode): boolean {
  return !!(node.sessionId || node.userId || node.input || node.output || node.metadata)
}

/**
 * Filters a tree to only include spans with LLMTracer data and their ancestors.
 * In verbose mode, returns the original tree.
 */
export function filterTreeByVerbosity(node: DecoratedNode, verboseMode: boolean): DecoratedNode | null {
  if (verboseMode) {
    return node
  }

  // Recursively filter children
  const filteredChildren = node.children
    .map(child => filterTreeByVerbosity(child, verboseMode))
    .filter((child): child is DecoratedNode => child !== null)

  // Include this node if it has LLM data or if any of its children are included
  const shouldInclude = hasLLMTracerData(node) || filteredChildren.length > 0

  if (shouldInclude) {
    return {
      ...node,
      children: filteredChildren,
    }
  }

  return null
}

export interface IDNode extends StringyNode {
  id: string
}

function makeList(root: StringyNode): IDNode[] {
  const list: IDNode[] = []

  function traverse(node: StringyNode) {
    list.push({...node, id: node.spanId})
    for (const child of node.children) {
      traverse(child)
    }
  }
  traverse(root)

  return list
}

/**
 * Computes both full and filtered tree lists for the TraceList component.
 */
export function computeTreeLists(decoratedTreeData: {
  node: DecoratedNode
  minTime: number
  maxTime: number
  maxDepth: number
}): {
  fullList: IDNode[]
  shortList: IDNode[]
} {
  // Generate verbose tree
  const fixedTree = fixTimes(decoratedTreeData.node, decoratedTreeData.minTime, decoratedTreeData.maxTime)
  const stringifiedTree = stringifyTree(fixedTree)
  const fullList = makeList(stringifiedTree)

  // Generate filtered tree
  const filtered = filterTreeByVerbosity(decoratedTreeData.node, false)
  let shortList: IDNode[] = []
  if (filtered) {
    const fixedFiltered = fixTimes(filtered, decoratedTreeData.minTime, decoratedTreeData.maxTime)
    const stringifiedFiltered = stringifyTree(fixedFiltered)
    shortList = makeList(stringifiedFiltered)
  }

  return {
    fullList,
    shortList,
  }
}
